import{j as o}from"./visuals-CpS1c05r.js";import{CoachPage as i}from"./AnalyzeCoach-nDWOEXbZ.js";import"./icons-CurrNn9R.js";import"./index-Brrwy6Jt.js";import"./solvedBank-Bf66J874.js";import"./MathMD-C5ctdg_Z.js";import"./Markdown-CBvy5aGR.js";import"./SolvedBank-NvDOGaJ2.js";import"./MinitabFigure-oiZp6MKd.js";const n=[4.94,5.13,4.94,4.92,4.77,4.95,5.28,5.11,5.26,5.06,5.1,5.05,4.98,5.95,5.13,5.12,4.88,4.86,4.78,4.88],r=[24.1,25.5,22.9,25.2,23.7,23.7,26.3,24.2,23.9,24.9,25.4,24,24.7,25.6,29.4,25.4,23.4,22.8,23,23.7],l=[null,1.4,2.6,2.3,1.5,0,2.6,2.1,.3,1,.5,1.4,.7,.9,3.8,4,2,.6,.2,.7],h=[4.86,4.92,5.29,5.01,5.01,5.07,4.69,5.24,5.06,5.01,5.16,5.09,5.24,5.05,5.13,6.03,5.24,5.39,5,5.29],c=[.93,.96,.65,1.48,.25,1.15,.59,1.45,.38,1.15,.64,.82,.81,.44,1.01,.75,1.06,1.43,.65,.52],d=[49.16,50.09,50.25,50.28,50.62,50.01,50.75,50.78,50.08,49.21,50.09,49.5,53.56,49.84,49.23,49.91,49.86,49.82,49.89,48.75],u=[2.59,1.88,1.54,3.34,1.39,1.25,2.45,2.46,3.04,2.26,2.27,2.24,2.13,2.37,2.26,2.46,2.35,2.77,2.06,1.51],m=[{topic:"5.1.1",title:"Control Methods for 5S",oneLine:"5S keeps the workplace organised so the project gains do not slip away: Sort, Straighten and Shine do the work, Standardize and Sustain hold it in place.",explain:["**5S** is a Lean tool for organising a workplace. In the Control phase it is a **control method**. It keeps the work area in order so the improvement from your project does not slowly disappear.","5S is the **base of the Lean pyramid**: 5S → Visual Factory → Standardized Work → Kaizen → Kanban. Each level needs the levels below it. So when the exam asks which Lean tool comes first, the answer is 5S.","The five S words, in order: **Sort** (keep only what the work needs), **Straighten** (a place for everything, everything in its place), **Shine** (clean, so problems are easy to see), **Standardize** (rules and visual controls that keep the first three in place) and **Sustain** (discipline: checklists, audits, habits). The Japanese words are Seiri, Seiton, Seiso, Seiketsu and Shitsuke.","The first three S's are **workplace actions**. The last two are **sustaining actions**. The last two are what make 5S a *control*. Without them, the area slides back to the old mess within weeks.","How to decide 5S is needed: **outliers** in the project metric, or a **loss of the initial gains**. How 5S is held in place: **standards + visual controls + checklists and audits + discipline**."],example:`**Service desk shared drive.** A project cut ticket handling time, but results start to drift. Agents waste minutes hunting for the right fix document.

- **Sort:** every file goes into *useful* (keep), *useless* (delete now) or *unknown* (hold for 30 days, then remove if nobody used it).
- **Straighten:** each fix has **one** fixed home in the knowledge base, with clear names.
- **Shine:** broken links and old versions are cleaned every week.
- **Standardize:** a naming rule and a colour-coded status on each page (a visual control).
- **Sustain:** a weekly checklist, and the team lead audits it every Friday. The audit score is posted on the team board next to the handling-time chart.`,readIt:["Read the scenario for the **symptom**: outliers or lost gains after a project → the area needs 5S.","Match the action to the S: removing unused items = **Sort**; labels, shadow boards, fixed places = **Straighten**; cleaning that reveals problems = **Shine**.","Rules and visual controls that keep the first three S's alive = **Standardize**.","Checklists, schedules, audits and leader follow-up = **Sustain** (not another clean-up campaign)."],remember:["Order: Sort → Straighten → Shine → Standardize → Sustain.","Japanese: Seiri, Seiton, Seiso, Seiketsu, Shitsuke.","First three S's = workplace actions; last two = sustaining actions.","5S is the foundation of the pyramid: 5S → Visual Factory → Standardized Work → Kaizen → Kanban.","Sort groups: useful (keep), useless (remove now), unknown (hold for a set time).","ABC storage: A daily = arm's reach, B weekly = nearby, C monthly or quarterly = remote."],traps:['"Unknown" items are not thrown away at once; they are held for a set time first.','Standardize is not "write an SOP for the process"; it is the rules that keep Sort, Straighten and Shine in place.',"Sustain means discipline, checklists and audits, not a second big clean-up day.","Kanban or Kaizen before 5S is wrong; 5S is the base of every other Lean control."],video:[{kind:"title",say:"Five S as a control method. How to keep the workplace organised so your project gains stay.",title:"Control Methods for 5S",sub:"The base of every Lean control"},{kind:"bullets",say:"The five S words come in a fixed order. Sort keeps only what the work needs. Straighten gives everything a fixed place. Shine cleans, so problems show. Standardize writes the rules. Sustain is the discipline to keep doing it.",title:"The five S words",bullets:["1 Sort · 2 Straighten · 3 Shine","4 Standardize: rules + visual controls","5 Sustain: checklists, audits, discipline","Base of the Lean pyramid"]},{kind:"compare",say:"The first three S words are workplace actions. The last two are sustaining actions. In the Control phase, the last two matter most, because they stop the area sliding back.",title:"Do it, then hold it",left:{head:"Workplace actions",points:["Sort","Straighten","Shine"]},right:{head:"Sustaining actions",points:["Standardize","Sustain",'This is the "control" part']}},{kind:"figure",say:"Here are two teams after a five S event. Team A kept a weekly checklist and audit, so its score stayed high. Team B stopped after the clean up, and its score fell back. Without sustain, the gains disappear.",title:"Why Sustain matters",figure:{kind:"lines",title:"5S Audit Score by Week",xLabels:["W1","W2","W3","W4","W5","W6","W7","W8"],series:[{name:"Team A (weekly audit)",values:[62,78,85,88,90,91,92,92]},{name:"Team B (no follow-up)",values:[60,80,86,82,75,70,66,63]}],yLabel:"Audit score (%)",xLabel:"Week"},callouts:["Both teams improved after the event","Team A sustained with checklists and audits","Team B slid back: lost gains"]},{kind:"steps",say:"To make five S stick: sort every item into useful, useless or unknown. Give each item a fixed, labelled place. Clean, so problems show. Then set a checklist, and audit it on a schedule.",title:"Make 5S stick",steps:["Sort: useful, useless, unknown (hold)","Straighten: a labelled home for each item","Shine: clean so problems are visible","Standardize + Sustain: checklist and audit"]},{kind:"callout",say:"Remember. Five S is the foundation. Standardize and sustain are what turn a clean up into a control.",big:"Standardize + Sustain turn a clean-up into a control",small:"5S is the base of the Lean pyramid"}]},{topic:"5.1.2",title:"Kanban",oneLine:"Kanban is a pull signal, a card or an empty slot, that tells a step to start work only when the next step needs it, so work-in-process stays small.",explain:["**Kanban** is Japanese for a **signal or card**. It is a signal to begin work. The signal can be a small card or a physical sign such as an **empty container**.","Kanban is a **pull** system. In a **push** system, each step works to a forecast and sends work forward, so piles build up. In a **pull** system, a step works **only when the next step signals a need**. This caps **work-in-process (WIP)**, the work that is started but not finished, and attacks the wastes of inventory, overproduction and waiting.","The book names **two types**. **Finished-goods Kanban** (intra-process) controls production inside a process; it includes the **Signal Kanban** and the **P.I.K.** (Production Instruction Kanban). **Incoming-material Kanban**, also called **Withdrawal** or inter-process Kanban, pulls material from a supplying department and regulates WIP between two processes.","Kanban sits at the **top of the Lean pyramid**. It needs 5S, Visual Factory, Standardized Work and ongoing Kaizen first. Installed too early, it **will backfire**. It is **not a quick fix** for big inventory problems, poor planning or unstable demand.","In IT and contact centres, Kanban appears as a **board with WIP limits** per column. When a column is full, no new ticket can enter. The empty slot is the signal, just like the empty container."],example:`**Provisioning orders.** A team had 140 open orders and long waiting times. After 5S of the order queue and standard work per order type, it set WIP limits: Validate 6, Configure 8, Test 4. A new order is pulled only when a slot frees up.

Sizing a card loop (a common textbook formula; the book gives none). The desk uses 200 spare modules a day, refill takes half a day, safety factor 10%, 20 modules per bin:

$$N=\\dfrac{200\\times 0.5\\times 1.10}{20}=\\dfrac{110}{20}=5.5$$

Round **up** → **6 Kanbans**. A part of a card does not exist.`,readIt:['Keyword "signal to begin work", "card", "empty bin" or "WIP limit" → Kanban.','"Kanban works best with a ___ system" → **pull**.',"Pulling material from a supplier or another department → **Withdrawal** (incoming-material) Kanban.","Asked what must exist before Kanban → the lower pyramid tools: 5S, Visual Factory, Standardized Work, Kaizen."],remember:["Kanban = signal or card; a signal to begin work.","Pull, not push: work starts only when the next step asks.","Finished-goods (intra-process): Signal Kanban and P.I.K.","Incoming-material = Withdrawal = inter-process; regulates WIP between two processes.","Top of the pyramid: needs 5S, Visual Factory, Standardized Work and Kaizen first.","Needs stable demand, small standard card quantities, near-zero defects, consistent cycle times."],traps:['"Withdrawal Kanban" belongs to incoming material, not finished goods.',"Kanban does not fix fluctuating demand or huge inventory; the book says it is not a quick fix.","Starting Kanban before 5S and standard work makes it backfire.","When calculating the number of cards, always round up."],video:[{kind:"title",say:"Kanban. A simple signal that pulls work through the process.",title:"Kanban",sub:"A pull signal that limits work-in-process"},{kind:"compare",say:"In a push system, every step works to a forecast, and work piles up. In a pull system, a step starts only when the next step sends a signal. Kanban is that signal. It can be a card or an empty bin.",title:"Push vs pull",left:{head:"Push",points:["Work to a forecast","Piles of WIP build up","Long waiting times"]},right:{head:"Pull (Kanban)",points:["Start only on a signal","Card or empty container","WIP stays small"]}},{kind:"figure",say:"Here a provisioning team set work in process limits in week four. Open orders fell from about one hundred forty to about fifty, because new orders were pulled only when a slot was free.",title:"WIP limits at work",figure:{kind:"lines",title:"Open Provisioning Orders by Week",xLabels:["W1","W2","W3","W4","W5","W6","W7","W8"],series:[{name:"Open orders",values:[140,138,142,120,90,70,58,52]}],yLabel:"Open orders",xLabel:"Week"},callouts:["WIP limits start in W4","Orders pulled only when a slot frees","Less waiting in piles"]},{kind:"bullets",say:"The book names two types. Finished goods Kanban controls production inside a process. It includes the signal Kanban and the P I K. Incoming material Kanban, also called withdrawal Kanban, pulls material from another department.",title:"Two types of Kanban",bullets:["Finished-goods (intra-process): make","Includes Signal Kanban and P.I.K.","Incoming-material = Withdrawal: get","Withdrawal regulates WIP between processes"]},{kind:"decision",say:"Before you start Kanban, ask one question. Are five S, visual factory, standard work and kaizen already in place? If yes, Kanban can work. If no, build those first, or Kanban will backfire.",title:"Ready for Kanban?",question:"Are 5S, Visual Factory, Standard Work and Kaizen in place?",yes:"Kanban can succeed",no:"Build the lower levels first"},{kind:"callout",say:"Remember. Kanban is a pull signal at the top of the Lean pyramid. It is not a quick fix.",big:"Kanban = pull signal, top of the pyramid",small:"Withdrawal Kanban = incoming material"}]},{topic:"5.1.3",title:"Poka-Yoke (Mistake Proofing)",oneLine:"Poka-yoke designs the process so an error cannot happen, or is caught and stopped at once, which makes it the strongest control you can put in place.",explain:["**Poka-yoke** is Japanese for **mistake proofing**. People will always make **errors**: they forget, mix things up or misread. An error is the cause. A **defect** is the result, a bad output. Poka-yoke breaks the link, so the error never becomes a defect that reaches the customer.",`It has two faces. **Prevention** (the book's **Type 1 corrective action, a countermeasure**) removes the error condition by design: "the defect will never be created". **Detection** (the book's **Type 2, a flag**) spots the error at once and **shuts the step down**, so the defect does not move forward.`,"The book ranks controls from strongest to weakest: **Type 1 prevention** → **Type 2 detection with shut-down** → **SPC with trained, empowered staff** → **Type 3 inspection** → **SOP or training alone**. Inspection finds defects only *after* they are made. Training asks people not to make mistakes, which is the weakest control.","Common ways to sense an error (general practice): **contact** (shape or a check of a feature, like a plug that fits one way), **fixed-value** (a set number of items must be done) and **motion-step** (steps must happen in order, like a form that will not submit until required fields are valid). A **shut-down** is stronger than a **warning**, because people can ignore a warning.","How to choose: use the FMEA to find the highest-risk failure modes. Ask first: can I **remove the error by design**? If not, can I **detect it and stop** at once? Only then fall back on SPC, inspection or procedures."],example:`**Billing tariff codes.** Wrong tariff codes cause 3% of invoices to be re-issued. Three options:

- **A.** Train billing staff again → weakest control.
- **B.** Audit 100 invoices a week → inspection (Type 3); finds errors after they happen.
- **C.** The order system shows **only the tariffs valid** for the customer's product, so a wrong code **cannot** be chosen → **Type 1 prevention**.

The team chooses **C**. A second guard: the system **blocks** closing an order with a missing code (Type 2 detection with shut-down). The FMEA occurrence score drops and the RPN is recalculated in the control plan.`,readIt:['"Which control is most effective?" → mistake proofing that **prevents** the error (Type 1).',"The defect can still be made, but the step stops so it cannot move on → **detection** poka-yoke (Type 2).","Audits and 100% checks → **inspection** (Type 3), not poka-yoke prevention.","Training, SOPs and reminders → the **weakest** controls."],remember:["Poka-yoke = mistake proofing.","Type 1 countermeasure = prevention: the defect is never created (strongest).","Type 2 flag = detection: catch the error and shut down so the defect does not move on.","Ranking: prevention > detection > SPC with empowered staff > inspection > SOP or training.","Shut-down beats a warning light or sound.","Use the FMEA to pick where to mistake-proof; recalculate the RPN after."],traps:["A warning alarm is weaker than a shut-down, because a person can ignore it.","Inspection finds defects after they are made; it is not prevention.","Retraining staff feels natural, but it is the weakest control on the list.","Detection poka-yoke stops the defect moving forward; it does not stop it being made."],video:[{kind:"title",say:"Poka yoke. Mistake proofing, the strongest control in the Control phase.",title:"Poka-Yoke",sub:"Mistake proofing"},{kind:"compare",say:"Poka yoke has two forms. Prevention changes the design so the error cannot happen at all. Detection catches the error at once and stops the step, so the defect cannot move on. Prevention is stronger.",title:"Prevention vs detection",left:{head:"Type 1: Prevention",points:["Removes the error condition","Defect is never created","Strongest control"]},right:{head:"Type 2: Detection",points:["Spots the error at once","Shuts the step down","Defect cannot move on"]}},{kind:"steps",say:"Here is the book ranking of controls, from strongest to weakest. Prevention. Then detection with shut down. Then S P C with trained, empowered staff. Then inspection. And last, a procedure or training on its own.",title:"Ranking of controls",steps:["Type 1: prevention by design","Type 2: detect and shut down","SPC with empowered staff","Type 3: inspection and audits","SOP or training alone (weakest)"]},{kind:"figure",say:"Where should you mistake proof first? This Pareto of invoice re issues shows wrong tariff codes are the biggest cause. A drop down that shows only valid tariffs makes that error impossible.",title:"Pick the target",figure:{kind:"pareto",title:"Pareto of Invoice Re-issue Causes",categories:[{name:"Wrong tariff code",count:46},{name:"Wrong address",count:18},{name:"Missing discount",count:12},{name:"Duplicate order",count:8},{name:"Other",count:6}],yLabel:"Re-issued invoices"},callouts:["Biggest cause: wrong tariff code","Fix: show only valid tariffs (Type 1)","Cannot choose a wrong code"]},{kind:"decision",say:"Ask one question. Can the error be removed by design? If yes, do it. That is prevention. If no, detect it at once and stop the process.",title:"Choose the control",question:"Can the error be removed by design?",yes:"Prevent it (Type 1)",no:"Detect and shut down (Type 2)"},{kind:"callout",say:"Remember. The most effective control makes the mistake impossible. Training is the weakest.",big:"Best control: make the error impossible",small:"Prevention > detection > SPC > inspection > training"}]},{topic:"5.2.1",title:"Data Collection for SPC",oneLine:"SPC separates normal noise (common cause) from real signals (special cause), and it only works when the data are sampled without bias in rational subgroups, often enough to catch a shift.",explain:["**SPC** (Statistical Process Control) uses **control charts** to watch a process over time. Its job is to tell **common-cause** variation (the normal, random noise of a stable process) from **special-cause** variation (something unusual that has a cause you can find). Common cause → **leave the process alone**; adjusting it is **tampering** and adds variation. Special cause → **investigate and act**.","The book makes a split: charting a critical **input (X)** is **SPC**, statistical process **control**; charting an **output (Y)** is **SPM**, statistical process **monitoring**. You control a Y by controlling its X's. A chart tells you the process changed, but **not why**.","Control limits come from the **process data** (the voice of the process). **Specification limits** come from the customer and are **not** drawn on a control chart. So a process **in control is stable, but not necessarily capable**.","A **rational subgroup** is a small sample made under **very similar conditions in a short time**, often **3 to 5 consecutive units** from one source. The spread *inside* subgroups sets the limits, so it must hold common cause only. Mix agents, shifts or machines inside a subgroup and the limits get too wide; real causes are **buried**. Five items from five machines at the same time is **not** rational: use a separate chart per stream.","Sample while the process runs **normally**, with no bias (not only the morning shift). Sample at least **10 times more often** than the process goes out of control; when unsure, sample **more often**. Collect about **20 to 25 subgroups** before calculating limits. Then pick the chart: continuous data with n = 1 → **I-MR**, 2 to 5 → **Xbar-R**, 10 or more → **Xbar-S**."],example:`**Call centre sampling plan.** The average handling time goes out of control about **twice a month**. Sample at least ten times that rate:

$$\\dfrac{2\\times 10}{1\\text{ month}}=20\\text{ subgroups per month}$$

That is about **one subgroup per working day**. A weekly sample (about 4 a month) would be too rare: a shift could run for days and the customer would suffer first.

**Subgroup:** 5 consecutive calls handled by **one** queue in the same hour, not one call from each of five queues.`,readIt:["Points randomly scattered inside the limits, no patterns → **common cause only**: do not adjust.","A point beyond a limit, or a pattern (e.g. 9 in a row on one side) → **special cause**: investigate.","Control limits are calculated from the data; spec limits do not belong on the chart.","Rational subgroup check: same source, same conditions, short time, consecutive units."],remember:["Common cause = normal noise → leave it; special cause = signal → investigate and act.","SPC = charting inputs (X's); SPM = charting outputs (Y's).","Rational subgroup = similar conditions, short time; often 3–5 consecutive units.","Sample at least 10 times more often than out-of-control events; unsure → sample more.","About 20–25 subgroups before calculating limits.","n = 1 → I-MR; 2–5 → Xbar-R; 10 or more → Xbar-S."],traps:['"One part from each of five machines at the same time" looks neat but is NOT a rational subgroup.',"In control does not mean capable: spec limits are not on the chart.","Adjusting the process for a common-cause point is tampering and increases variation.","Biased sampling (only one shift, only one vendor) makes the chart invalid."],video:[{kind:"title",say:"Data collection for S P C. Good charts start with good samples.",title:"Data Collection for SPC",sub:"Noise vs signal, and how to sample"},{kind:"compare",say:"S P C has one job. It separates common cause from special cause. Common cause is the normal noise of a stable process. Leave it alone. Special cause is unusual, and has a reason you can find. Investigate it.",title:"Common vs special cause",left:{head:"Common cause",points:["Normal random noise","Inside the limits, no pattern","Do not adjust"]},right:{head:"Special cause",points:["Unusual, has a findable reason","Beyond a limit or a pattern","Investigate and act"]}},{kind:"figure",say:"This chart shows the daily average handling time. Most days bounce around five minutes. That is common cause. Day fourteen is above the upper control limit. That is a special cause. Find out what happened that day.",title:"Spot the signal",figure:{kind:"control",title:"I Chart of Daily Average Handling Time",panels:[{label:"Individual Value",points:n,cl:5.054,ucl:5.612,lcl:4.497,flags:[{i:13,test:"1"}],clLabel:"X̄=5.054"}],xLabel:"Day"},callouts:["Most days: common cause only","Day 14 above the UCL: special cause","Limits come from the data, not the specs"]},{kind:"bullets",say:"Collect data in rational subgroups. That means a few units made under the same conditions in a short time, like five calls in a row from one queue. Do not mix queues or shifts inside one subgroup, or real causes get buried.",title:"Rational subgroups",bullets:["Same source, same conditions, short time","Often 3 to 5 consecutive units","Do not mix queues or shifts inside","Separate chart for each stream"]},{kind:"steps",say:"Build your sampling plan in this order. Choose the input or output to chart. Form rational subgroups. Pick the chart. Then set the frequency, at least ten times more often than the process goes out of control.",title:"Build the sampling plan",steps:["Choose the X or Y to chart","Form rational subgroups, no bias","Pick the chart by data type and n","Sample 10x more often than upsets"]},{kind:"callout",say:"Remember. Common cause, leave it alone. Special cause, investigate. And in control does not mean capable.",big:"Common cause: leave it. Special cause: act.",small:"In control does not mean capable"}]},{topic:"5.2.2",title:"I-MR Chart",oneLine:"The I-MR chart is for single values (subgroup size 1): the I chart tracks the level, the MR chart tracks the jump between neighbouring points.",explain:["The **I-MR chart** (Individuals and Moving Range) is used when each data point is a **single value**, so the subgroup size is **1**. Typical cases: one figure per day or month, a destructive test, a well-mixed batch, slow or costly data. The book says it is used for SPC on **most inputs**.","It is really two charts. The **I chart** plots each value, with the average as the centre line. The **MR chart** plots the **moving range**: the size of the jump between two **neighbouring** points. With $k$ points you get $k-1$ moving ranges.",`Limits: the I chart uses $\\bar{X}\\pm 2.66\\,\\overline{MR}$. The MR chart has an upper limit of $3.267\\,\\overline{MR}$ and a lower limit of 0. The sigma comes from the short-term jumps, not from the overall standard deviation of all the data:

$$\\hat{\\sigma}=\\dfrac{\\overline{MR}}{1.128}$$`,"Single values vary more than averages, so the I chart has **wider limits** and is **less sensitive** than an Xbar chart. That is the price of having only one value per point.","How to read it: **MR chart first**. If the short-term variation is unstable, the I-chart limits are not reliable. Then read the I chart: a point beyond a limit, or a pattern such as 9 in a row on one side of the centre line, signals a special cause."],example:`**Provisioning lead time.** One value per day (hours) for 20 days. Minitab: $\\bar{X}=24.59$, $\\overline{MR}=1.505$.

- I chart: $2.66\\times 1.505=4.00$ → **UCL 28.59**, **LCL 20.59**.
- MR chart: $3.267\\times 1.505=4.92$ → **UCL 4.92**, LCL 0.

Read the MR chart first: every moving range is below 4.92, so short-term variation is stable. Now the I chart: **day 15 = 29.4 hours**, above the UCL. That is a special cause. The team finds a core-network change freeze that day and adds it to the OCAP (out-of-control action plan).`,readIt:["Read the **MR chart first**: any MR above its UCL? If yes, the I limits are not trustworthy yet.","Then the **I chart**: any point beyond the UCL or LCL? → special cause, investigate (Test 1).","Look for patterns: 9 points in a row on one side, 6 in a row rising or falling.","No signals → common cause only: keep plotting, do not adjust."],remember:["I-MR = subgroup size 1 (one value per day, batch or period).","MR = the jump between two neighbouring points; k points give k − 1 MRs.","I chart limits = X̄ ± 2.66 × MR̄.","MR chart UCL = 3.267 × MR̄; LCL = 0.","Sigma estimate = MR̄ divided by 1.128 (not the overall standard deviation).","Wider limits and less sensitive than Xbar-R."],traps:["Using A₂ or 3 × MR̄ for the I chart limits; the constant is 2.66.","Averaging the moving ranges over k instead of k − 1.","Using the overall standard deviation of all the data instead of the moving-range estimate.","Drawing specification limits on the chart; limits come from the process."],video:[{kind:"title",say:"The I M R chart. Individuals and moving range, for one value at a time.",title:"I-MR Chart",sub:"Individuals and Moving Range, n = 1"},{kind:"bullets",say:"Use the I M R chart when each point is a single value. One number per day, a destructive test, or slow, costly data. The I chart shows the level. The moving range chart shows the jump between neighbours.",title:"When to use it",bullets:["Subgroup size 1: one value per point","Daily or monthly figures, batch tests","I chart = level","MR chart = jump between neighbours"]},{kind:"figure",say:"Here is the daily provisioning lead time. First the moving range chart. All points are below its upper limit, so short term variation is stable. Now the I chart. Day fifteen is above the U C L of about twenty eight point six hours. That is a special cause.",title:"Read MR first, then I",figure:{kind:"control",title:"I-MR Chart of Provisioning Lead Time",panels:[{label:"Individual Value",points:r,cl:24.59,ucl:28.59,lcl:20.59,flags:[{i:14,test:"1"}],clLabel:"X̄=24.59"},{label:"Moving Range",points:l,cl:1.505,ucl:4.92,lcl:0,clLabel:"MR̄=1.505"}],xLabel:"Day"},callouts:["MR chart in control: limits are valid","Day 15 = 29.4 h, above UCL 28.59","Limits: X̄ ± 2.66 × MR̄"]},{kind:"steps",say:"Read it in this order. Check the moving range chart. Then look for points beyond the limits on the I chart. Then look for patterns, like nine in a row on one side. Act only on a signal.",title:"How to read it",steps:["Check the MR chart first","I chart: any point beyond the limits?","Patterns: 9 on one side, 6 trending","Signal → OCAP; no signal → leave it"]},{kind:"decision",say:"So, is any point outside the limits, or is a pattern test failed? If yes, investigate the special cause. If no, it is common cause. Do not adjust the process.",title:"Act or not?",question:"Any point beyond a limit or a failed test?",yes:"Special cause: investigate",no:"Common cause: do not adjust"},{kind:"callout",say:"Remember. I M R means subgroup size one. The I chart limits are the mean plus or minus two point six six times the average moving range.",big:"n = 1 → I-MR; limits = X̄ ± 2.66 MR̄",small:"Read the MR chart first"}]},{topic:"5.2.3",title:"Xbar-R Chart",oneLine:"The Xbar-R chart is for small subgroups of continuous data (usually 2–5): the Xbar chart tracks the subgroup averages, the R chart tracks the spread inside each subgroup.",explain:["The **Xbar-R chart** is a matched pair for **continuous data in small subgroups**. The book's selection tree gives subgroup size **2 to 5**. Each point is a subgroup, for example 5 calls in a row from one queue.","The **Xbar chart** plots each **subgroup average**: it shows the process **level**. The **R chart** plots each **subgroup range** (largest minus smallest): it shows the short-term **spread**. Level and spread usually need different fixes, so we watch both.","Why averages? An average of 5 values moves less than a single value. So the Xbar chart has **tighter limits** and catches a shift in the mean **faster** than an I chart. It is more sensitive.","Limits: Xbar chart $\\bar{\\bar{X}}\\pm A_2\\bar{R}$; R chart upper limit $D_4\\bar{R}$, lower limit $D_3\\bar{R}$. The constants depend on n. For **n = 5**: $A_2=0.577$, $D_3=0$, $D_4=2.114$.","How to read it: **R chart first**. The Xbar limits are built from $\\bar{R}$, so if the R chart is out of control, the Xbar limits are wrong. Then read the Xbar chart for points beyond the limits and run patterns. The **most common error** with Xbar-R is **poor subgrouping**."],example:`**Handling time, 5 calls per hour.** 20 subgroups of n = 5. Minitab: $\\bar{\\bar{X}}=5.139$ min, $\\bar{R}=0.856$ min.

- Xbar chart: $0.577\\times 0.856=0.494$ → **UCL 5.633**, **LCL 4.645**.
- R chart: $2.114\\times 0.856=1.810$ → **UCL 1.810**, LCL 0.

R chart first: every range is below 1.810, so the spread is stable and the Xbar limits are valid. Xbar chart: **subgroup 16 averages 6.03 min**, above the UCL. The level jumped for that hour: a CRM slowdown. Special cause → follow the OCAP.`,readIt:["Read the **R chart first**: any range above its UCL? If yes, fix the spread before trusting the Xbar chart.","Then the **Xbar chart**: any subgroup average beyond the UCL or LCL? → special cause.","Check the run tests: 9 in a row on one side, 6 in a row rising or falling.","No signals → common cause: keep plotting against the same frozen limits."],remember:["Xbar-R: continuous data, rational subgroups of 2–5.","Xbar chart = level; R chart = spread inside the subgroup.","Xbar limits = X̿ ± A₂ × R̄; R chart UCL = D₄ × R̄, LCL = D₃ × R̄.","n = 5: A₂ = 0.577, D₃ = 0, D₄ = 2.114.","Read the R chart first.","More sensitive than I-MR; most common error = wrong subgrouping."],traps:['"Interpret the Xbar chart first" is wrong; the range chart comes first.',"Mixing up constants: D₄ belongs to the R chart, A₂ to the Xbar chart.","Specification limits are not control limits; control limits come from the data.","Subgroups of 10 or more → Xbar-S, not Xbar-R."],video:[{kind:"title",say:"The x bar R chart. Averages and ranges for small subgroups.",title:"Xbar-R Chart",sub:"Subgroups of 2 to 5"},{kind:"compare",say:"The chart is a pair. The x bar chart plots the average of each subgroup. It shows the level. The R chart plots the range inside each subgroup. It shows the spread.",title:"Two charts, two jobs",left:{head:"Xbar chart",points:["Subgroup averages","Shows the process level","Limits: X̿ ± A₂ R̄"]},right:{head:"R chart",points:["Subgroup ranges (max − min)","Shows short-term spread","UCL = D₄ R̄"]}},{kind:"figure",say:"Here are twenty subgroups of five calls. Start with the R chart. All ranges are inside the limits, so the spread is stable. Now the x bar chart. Subgroup sixteen is above the U C L. The level jumped for that hour. That is a special cause.",title:"Read R first, then Xbar",figure:{kind:"control",title:"Xbar-R Chart of Handling Time",panels:[{label:"Sample Mean",points:h,cl:5.139,ucl:5.633,lcl:4.645,flags:[{i:15,test:"1"}],clLabel:"X̿=5.139"},{label:"Sample Range",points:c,cl:.856,ucl:1.81,lcl:0,clLabel:"R̄=0.856"}],xLabel:"Subgroup (n = 5)"},callouts:["R chart in control: Xbar limits valid","Subgroup 16 above UCL 5.633","n = 5: A₂ 0.577, D₄ 2.114"]},{kind:"steps",say:"Read it in this order. First the R chart. If it is out of control, the x bar limits cannot be trusted. Then the x bar chart, points beyond the limits. Then the run patterns.",title:"How to read it",steps:["R chart first: spread stable?","Xbar chart: points beyond limits?","Run tests: 9 on one side, 6 trending","Signal → investigate with the OCAP"]},{kind:"callout",say:"Remember. Small subgroups, use x bar R. Read the range chart first. And for subgroups of ten or more, switch to x bar S.",big:"Subgroups of 2–5 → Xbar-R; read R first",small:"Most common error: wrong subgrouping"}]},{topic:"5.2.7",title:"Xbar-S Chart",oneLine:"The Xbar-S chart works like Xbar-R, but it measures spread with the subgroup standard deviation, so it is used for larger subgroups of about 10 or more.",explain:["The **Xbar-S chart** is the partner of Xbar-R for **larger subgroups**. The book's selection tree: continuous data with subgroup size **10 or more → Xbar-S**.","The **Xbar chart** still plots subgroup **averages** (the level). The **S chart** plots each subgroup's **standard deviation** (the spread). The standard deviation measures how far the values sit from their average, using **every** value.","Why switch from R to S? The range uses only **two values**, the largest and the smallest. With 10 or more values it throws away most of the information, and one **outlier** can distort it. S uses all the values, so it estimates the spread more precisely.","Limits: Xbar chart $\\bar{\\bar{X}}\\pm A_3\\bar{s}$; S chart upper limit $B_4\\bar{s}$, lower limit $B_3\\bar{s}$. For **n = 10**: $A_3=0.975$, $B_3=0.284$, $B_4=1.716$. Note that the S chart now has a **lower limit above 0**. A point below it means unusually low spread: maybe a real gain, maybe copied data. Investigate either way.","How to read it: exactly like Xbar-R. **S chart first**; if the spread is out of control, the Xbar limits are not valid. Then the Xbar chart for points beyond the limits and patterns."],example:`**Network latency, 10 test calls per hour.** 20 subgroups of n = 10. Minitab: $\\bar{\\bar{X}}=50.08$ ms, $\\bar{s}=2.231$ ms.

- Xbar chart: $0.975\\times 2.231=2.175$ → **UCL 52.26**, **LCL 47.91**.
- S chart: $1.716\\times 2.231=3.828$ → **UCL 3.83**; $0.284\\times 2.231=0.634$ → **LCL 0.63**.

S chart first: all standard deviations sit between 0.63 and 3.83, so the spread is stable. Xbar chart: **subgroup 13 averages 53.56 ms**, above the UCL. The level rose for that hour: a routing change on one link. Special cause → investigate.`,readIt:["Read the **S chart first**: any point above the UCL **or below the LCL**? If yes, sort out the spread first.","Then the **Xbar chart**: any subgroup average beyond the limits? → special cause.","Check the run tests on the Xbar chart: 9 on one side, 6 trending.","Choosing between charts: subgroup size 10+ or outliers distort the range → Xbar-S."],remember:["Xbar-S: continuous data, subgroups of about 10 or more.","S = subgroup standard deviation; uses every value.","Xbar limits = X̿ ± A₃ × s̄; S chart UCL = B₄ × s̄, LCL = B₃ × s̄.","n = 10: A₃ = 0.975, B₃ = 0.284, B₄ = 1.716.","Read the S chart first, as with Xbar-R.","Book's reason for S over R: outliers can distort the range."],traps:['"Subgroups of 12 measurements" → Xbar-S, not Xbar-R.',"Using A₂ (an R-chart constant) with s̄; Xbar-S uses A₃.","Thinking the S chart LCL is always 0; for n = 10 it is above 0."],video:[{kind:"title",say:"The x bar S chart. Averages and standard deviations for large subgroups.",title:"Xbar-S Chart",sub:"Subgroups of 10 or more"},{kind:"compare",say:"Both charts track level and spread. x bar R uses the range, which looks at only two values. It suits small subgroups. x bar S uses the standard deviation, which uses every value. It suits subgroups of ten or more, and is less upset by outliers.",title:"Xbar-R vs Xbar-S",left:{head:"Xbar-R",points:["Subgroups of 2–5","Range: only max and min","Constants A₂, D₃, D₄"]},right:{head:"Xbar-S",points:["Subgroups of 10 or more","Std dev: uses every value","Constants A₃, B₃, B₄"]}},{kind:"figure",say:"Here are twenty subgroups of ten test calls. First the S chart. Every point is between its lower and upper limits, so the spread is stable. Now the x bar chart. Subgroup thirteen is above the U C L. The latency level jumped. That is a special cause.",title:"Read S first, then Xbar",figure:{kind:"control",title:"Xbar-S Chart of Latency",panels:[{label:"Sample Mean",points:d,cl:50.084,ucl:52.259,lcl:47.909,flags:[{i:12,test:"1"}],clLabel:"X̿=50.08"},{label:"Sample StDev",points:u,cl:2.231,ucl:3.828,lcl:.634,clLabel:"S̄=2.231"}],xLabel:"Subgroup (n = 10)"},callouts:["S chart in control, LCL above 0","Subgroup 13 above UCL 52.26","n = 10: A₃ 0.975, B₄ 1.716"]},{kind:"steps",say:"Read it the same way as x bar R. First the S chart, above the upper limit or below the lower limit. Then the x bar chart for points beyond the limits. Then the run patterns.",title:"How to read it",steps:["S chart first: spread stable?","Watch the S chart LCL too","Xbar chart: points beyond limits?","Run tests, then OCAP if a signal"]},{kind:"callout",say:"Remember. Subgroups of ten or more, use x bar S. Read the S chart first.",big:"Subgroups of 10+ → Xbar-S; read S first",small:"S uses every value; R uses only two"}]}],p=[{topic:"5.2.4",title:"U Chart",oneLine:"A U chart tracks defects per unit when the number of units checked changes from sample to sample.",explain:["First, two words. A **defect** is one flaw or error. A **defective** is a whole unit that is bad. One order form can have **several defects** (wrong address, missing ID, wrong plan) — those are defects. The U chart counts **defects**.","Use a **U chart** when you count defects **and the sample size changes**. Example: every day a team checks the new-line order forms that came in — 40 forms one day, 60 the next. You cannot compare raw counts, so you compare **defects per unit**.",`For each day, divide the defects by the forms checked: $u_i = c_i \\div n_i$. The centre line uses the **totals**, not the average of the daily values:

$$\\bar{u}=\\dfrac{\\text{total defects}}{\\text{total units inspected}}$$`,"The limits are $\\bar{u}$ plus or minus 3 standard errors, and the standard error uses **each day's own n**. So the limits **change every day**: a big sample gives **tight** limits, a small sample gives **wide** limits. The lines look like steps. A negative lower limit is set to **0**.","If the sample size is **always the same**, you can use the simpler **C chart** (count of defects). The book says a U chart can do everything a C chart can."],example:`**Order-form errors.** Over 15 days the team checked **731 forms** and found **187 errors**.

$$\\bar{u}=\\dfrac{187}{731}=0.256\\text{ errors per form}$$

On day 13 they checked **47 forms** and found **26 errors**: $u = 0.553$.

For $n = 47$ the UCL is $0.256 + 3\\sqrt{0.256 \\div 47} = 0.256 + 0.221 = 0.477$.

- 0.553 > 0.477 → **out of control** (special cause). Investigate day 13 — perhaps a new form version or a new agent.
- On a day with 62 forms the UCL is tighter (0.449), because a bigger sample gives a more precise rate.`,readIt:["Each point is defects per unit for that sample. Compare it with **its own** limits — they move with n.","A point above its UCL (or a run of 9 on one side, 6 trending, 14 alternating) = special cause → follow the response plan (OCAP).","Wide limits on a day = small sample that day. Tight limits = big sample.","All points inside and no patterns = stable. Do not adjust the process."],remember:["U chart = defects per unit; sample size may vary.","C chart = number of defects; sample size must be constant.","ū = total defects ÷ total units (not the average of the daily u values).","Limits change with each nᵢ: bigger n → narrower limits; negative LCL → 0.","Defect = one flaw (a unit can have many); defective = a whole bad unit."],traps:["Choosing a P chart just because n varies — P is for defectives (good/bad units), U is for defects.","Averaging the daily u values for the centre line instead of total defects ÷ total units.","Expecting flat limits: U chart limits vary with sample size.","Choosing a C chart when the number of units checked changes — use U."],video:[{kind:"title",say:"The U chart. How to track defects per unit when the sample size keeps changing.",title:"U Chart",sub:"Defects per unit, varying sample size"},{kind:"bullets",say:"First, a defect is one error. One order form can have many errors, such as a wrong address and a missing I D. The U chart counts defects. And because we check a different number of forms each day, it plots defects per form, not the raw count.",title:"What a U chart tracks",bullets:["Defect = one error; a unit can have many","Plots defects per unit (u = c ÷ n)","Sample size can change each day","Same sample size every time? C chart"]},{kind:"figure",say:"Here are fifteen days of order form errors. The centre line is the total errors divided by the total forms, about zero point two six errors per form. See how the limits step up and down. Small days have wide limits, big days have tight limits. Day thirteen is above its limit, so it is a special cause to investigate.",title:"Errors per order form",figure:{kind:"control",title:"U Chart of Order-Form Errors",xLabel:"Day",panels:[{label:"Errors per Form",points:[.25,.218,.271,.233,.229,.212,.267,.224,.238,.24,.237,.242,.553,.218,.227],cl:.256,ucl:[.496,.46,.475,.452,.512,.466,.482,.455,.49,.47,.502,.449,.477,.46,.485],lcl:[.016,.051,.037,.06,0,.045,.03,.057,.022,.041,.01,.063,.034,.051,.027],flags:[{i:12,test:"1"}],clLabel:"Ū=0.256"}]},callouts:["Ū = 187 errors ÷ 731 forms","Limits step with each day’s n","Day 13: 0.553 > UCL 0.477 → special cause"]},{kind:"decision",say:"How do you choose? If you count defects and the number of units checked changes, use a U chart. If the number checked is always the same, a C chart is enough.",title:"U or C?",question:"Counting defects — does the sample size vary?",yes:"U chart (defects per unit)",no:"C chart (count of defects)"},{kind:"callout",say:"Remember. Defects, with a sample size that changes, means a U chart. Its limits move with the sample size.",big:"Defects + varying sample size → U chart",small:"Centre line = total defects ÷ total units. Limits step with n."}]},{topic:"5.2.5",title:"P Chart",oneLine:"A P chart tracks the proportion of defective units, and it works even when the sample size changes.",explain:["A **defective** is a whole unit that is simply good or bad — pass or fail. A SIM activation either works or fails. A call is either answered in time or not. The P chart tracks the **proportion** (percentage) of defective units.","Use a **P chart** when you have **defectives** and the **sample size can change**. Example: the number of SIM activations is different every day, and you track the share that failed. The book calls it the **most common** attribute chart.",`For each sample, $p_i$ = defectives ÷ units checked. The centre line uses the totals:

$$\\bar{p}=\\dfrac{\\text{total defectives}}{\\text{total units inspected}}$$

The book says this centre line is also your **process capability** for that attribute (your average defective rate).`,"The limits are $\\bar{p}$ plus or minus 3 standard errors, and the standard error uses **each sample's own n**. So the limits are **uneven** — wider for small samples, tighter for big ones. A negative lower limit is set to 0. The book recommends **at least 20 samples** to set the limits, and samples are usually **larger than 50**.","Read each point against **its own** limits. A point above its UCL, or a pattern such as 9 in a row on one side, is a special cause → use the response plan (OCAP). The customer target is **not** drawn on the chart."],example:`**Failed SIM activations.** Over 15 days there were **2,980 activations** and **158 failures**.

$$\\bar{p}=\\dfrac{158}{2980}=0.053\\;(5.3\\%)$$

Day 12 had only **140 activations**, with **16 failures**: $p = 0.114$.

For $n = 140$ the UCL is $0.053 + 3\\sqrt{0.053 \\times 0.947 \\div 140} = 0.053 + 0.057 = 0.110$.

- 0.114 > 0.110 → **special cause** on day 12. Investigate.
- On a big day ($n = 260$) the UCL is only **0.095**. So a rate of 0.10 would be **inside** the limits on a 140-activation day but **outside** on a 260-activation day. Same rate, different decision — because of n.`,readIt:["Each point is the proportion defective for that sample; compare it with **its own** stepped limits.","Above the UCL → special cause; act with the OCAP. Below the LCL → investigate too (real improvement, or inspection missed defectives).","Use tests 1–4 only (beyond 3σ, 9 on one side, 6 trending, 14 alternating).","No signal → no adjustment, even if a point is above the centre line."],remember:["P chart = proportion defective; sample size may vary.","p̄ = total defectives ÷ total inspected; it is also the process capability for that attribute.","Limits vary with each nᵢ: bigger n → tighter limits; negative LCL → 0.","At least 20 samples to set the limits; samples usually > 50.","Most common attribute chart; it can do everything an NP chart can."],traps:["Thinking P chart limits are flat — they change with sample size.","Choosing P for defects (errors per form) — that is U. P is for defective units.","Using the total of all units in the square root instead of that sample's nᵢ.","Drawing the customer target (spec) on the chart as a control limit."],video:[{kind:"title",say:"The P chart. The most common chart for good or bad units.",title:"P Chart",sub:"Proportion defective, varying sample size"},{kind:"bullets",say:"A defective is a whole unit that is good or bad. A SIM activation works or it fails. The P chart plots the proportion of failures in each sample. The number of activations can change every day, and that is fine.",title:"What a P chart tracks",bullets:["Defective = whole unit good or bad","Plots proportion defective (p = d ÷ n)","Sample size may change","Centre line = total defectives ÷ total units"]},{kind:"figure",say:"Here are fifteen days of failed activations. The centre line is five point three percent. Look at the limits. They step up and down with each day’s sample size. Day twelve had only one hundred and forty activations, so its limits are wide. Even so, its rate of eleven point four percent is above the limit. That is a special cause.",title:"Failed SIM activations",figure:{kind:"control",title:"P Chart of Failed Activations",xLabel:"Day",panels:[{label:"Proportion",points:[.05,.055,.047,.052,.05,.047,.048,.056,.048,.054,.047,.114,.046,.055,.044],cl:.053,ucl:[.103,.098,.108,.096,.101,.105,.097,.106,.099,.096,.102,.11,.095,.101,.103],lcl:[.003,.008,0,.011,.005,.001,.009,0,.007,.01,.004,0,.011,.005,.003],flags:[{i:11,test:"1"}],clLabel:"P̄=0.053"}]},callouts:["P̄ = 158 ÷ 2980 = 0.053","Small n → wide limits; big n → tight","Day 12: 0.114 > UCL 0.110 → special cause"]},{kind:"steps",say:"To read a P chart, first work out the proportion for each sample. Then compare it with that sample’s own limits. If a point is beyond a limit, or a run breaks the rules, follow the response plan. If not, leave the process alone.",title:"How to read it",steps:["Proportion = defectives ÷ units checked","Compare with that point’s own limits","Check tests 1–4 for patterns","Signal → OCAP; no signal → no adjustment"]},{kind:"callout",say:"Remember. Defective units, with a sample size that changes, means a P chart. Its limits change with the sample size.",big:"Defectives + varying sample size → P chart",small:"Limits step with each sample’s n. Never draw the spec on it."}]},{topic:"5.2.6",title:"NP Chart",oneLine:"An NP chart plots the number of defective units in each sample, and it needs the same sample size every time.",explain:["The **NP chart** is the **count** version of the P chart. It also tracks **defectives** — whole units that are good or bad — but it plots the **number** of bad units, not the proportion.","Use it only when the **sample size is constant**. Example: a lab tests exactly **200 handsets** every day and counts how many fail. Because n is always 200, the counts can be compared fairly. Operators often find counts easier than percentages.","Why must n be constant? Ten failures out of 100 is bad; ten out of 1,000 is good. If n changes, the counts mean different things. So: **varying n → P chart**.",`The centre line is the average number defective per sample:

$$n\\bar{p}=\\dfrac{\\text{total defectives}}{\\text{number of samples}}$$

The limits are $n\\bar{p}$ plus or minus 3 standard errors, and they are **flat** (the same for every point). A negative lower limit is set to 0.`,"On the same constant-n data, the NP chart and the P chart give **the same signals** — the NP limits are just the P limits multiplied by n."],example:`**Handset tests.** Every day **200 handsets** are tested. Over 16 days, **160** failed.

$$n\\bar{p}=\\dfrac{160}{16}=10\\text{ failures per day}\\qquad \\bar{p}=\\dfrac{10}{200}=0.05$$

UCL $= 10 + 3\\sqrt{10 \\times 0.95} = 10 + 9.25 = 19.25$; LCL $= 10 - 9.25 = 0.75$.

- Day 11 had **22 failures** → 22 > 19.25 → **special cause**. Check that day's batch, supplier or test rig.
- If the lab started testing a different number of handsets each day, it should switch to a **P chart**.`,readIt:["Each point is a count of defective units in a fixed-size sample. The limits are flat lines.","Point above the UCL or a run/trend (tests 1–4) → special cause → response plan.","A point far below the centre line can be a real improvement — or missed inspection. Investigate both.","No signal → leave the process alone."],remember:["NP chart = number of defective units per sample; n must be constant.","np̄ = total defectives ÷ number of samples.","Limits are constant; negative LCL → 0.","NP and P on the same constant-n data give the same signals.","Varying n → P chart. Defects (not defectives) → C or U."],traps:["Using an NP chart when the sample size varies — use a P chart.","Choosing C because n is constant — C is for defects, NP is for defective units.","Centre line computed as total defectives ÷ total units — that is p̄, not np̄."],video:[{kind:"title",say:"The N P chart. Counting bad units in samples of the same size.",title:"NP Chart",sub:"Number defective, constant sample size"},{kind:"compare",say:"The N P chart and the P chart are partners. Both track defective units. The N P chart plots the count, and it needs the same sample size every time. The P chart plots the proportion, and the sample size can change.",title:"NP vs P",left:{head:"NP chart",points:["Number of defective units","Sample size constant","Flat limits"]},right:{head:"P chart",points:["Proportion defective","Sample size may vary","Limits step with n"]}},{kind:"figure",say:"A lab tests two hundred handsets every day. On average ten fail, so the centre line is ten. The upper control limit is about nineteen. The limits are flat, because the sample size never changes. Day eleven had twenty two failures. That is above the limit, so we look for a special cause.",title:"Failed handsets per day",figure:{kind:"control",title:"NP Chart of Failed Handsets (n = 200)",xLabel:"Day",panels:[{label:"Number Defective",points:[8,11,6,9,12,7,10,9,13,8,22,10,7,11,9,8],cl:10,ucl:19.25,lcl:.75,flags:[{i:10,test:"1"}],clLabel:"NP̄=10"}]},callouts:["NP̄ = 160 ÷ 16 days = 10","Flat limits: n is always 200","Day 11: 22 > UCL 19.25 → special cause"]},{kind:"decision",say:"So, for defective units, ask one question. Is the sample size always the same? If yes, you may use the N P chart. If no, use the P chart.",title:"NP or P?",question:"Defective units — is the sample size always the same?",yes:"NP chart (count defective)",no:"P chart (proportion defective)"},{kind:"callout",say:"Remember. Defective units with a constant sample size means an N P chart.",big:"Defectives + constant sample size → NP chart",small:"Sample size changes? Switch to the P chart."}]},{topic:"5.2.8",title:"CuSum Chart",oneLine:"A CuSum chart adds up the small differences from target over time, so a small, steady shift builds into a clear signal.",explain:["**CuSum** means **cumulative sum** — a running total. The chart adds up how far each point is from the **target**. It is a **special case** chart, used to catch **small shifts** in the mean that ordinary charts miss.","Why do ordinary charts miss them? An I chart or Xbar chart (a **Shewhart** chart) judges **each point on its own**. A shift of about 1 sigma stays inside the 3-sigma limits for a long time. CuSum **remembers**: small differences that point the same way keep adding up.","The book's key phrase: CuSum is used for the **same reasons as EWMA** (small shifts), **except that past data are as important as present data**. In CuSum every past point counts **equally**.","How it works (idea only): if the process is on target, plus and minus differences cancel and the sum stays near zero. If the mean creeps up, the sum **climbs steadily** until it crosses a **decision limit**. Where the slope **starts** tells you roughly **when** the shift began. The book says CuSum is complex and is done with **software**.","Do **not** use CuSum for big, sudden shifts — a normal Shewhart chart catches those faster and is easier for operators."],example:`**Call set-up time.** Target = 10 seconds, sigma = 1 second. After point 6 the mean creeps up to about 11 seconds.

- On an **I chart** (limits 7 to 13 s), every point is inside — **no signal**.
- The **upper CuSum** adds each small excess (above an allowance of 0.5 s): 0, 0, …, 0.4, 1.0, 1.3, 2.1, 2.6, 3.3, **4.2**.
- The decision limit is 4, so the CuSum **signals at point 13**. The rising slope starts at point 7 — that is when the shift began.`,readIt:["A flat line near zero = on target.","A steady upward (or downward) slope = the mean has moved above (or below) target.","A point beyond the decision limit = signal → investigate with the OCAP; look where the slope started to date the change.","Do not apply the zone tests (9 in a row, etc.) to CuSum points — they are not independent."],remember:["CuSum = cumulative sum of differences from target.","Use it to detect small, sustained shifts in the mean.","Book: same reasons as EWMA, except past data are as important as present data.","All past points have equal weight (EWMA weights recent data more).","Special case, less common; done with software."],traps:["Choosing CuSum for large, sudden shifts — a Shewhart chart (I-MR, Xbar-R) is better there.","Mixing up CuSum and EWMA: CuSum = equal weight to all history; EWMA = more weight to recent data.",'Thinking "no point outside the I chart limits" means no shift — small shifts hide inside the limits.'],video:[{kind:"title",say:"The Cu Sum chart. A running total that catches small shifts.",title:"CuSum Chart",sub:"Cumulative sum — small shifts, all history counts"},{kind:"bullets",say:"Cu Sum means cumulative sum. It adds up how far each point is from the target. Ordinary charts judge each point alone, so a small shift can hide inside the limits. Cu Sum remembers, so small steps that go the same way add up.",title:"The idea",bullets:["Adds up differences from target","Small shifts build into a signal","All past points count equally","Done with software"]},{kind:"figure",say:"Here is call set up time, with a target of ten seconds. In the top chart, every point is inside the limits. No signal. In the bottom chart, the Cu Sum starts to climb at point seven, and it crosses the decision limit at point thirteen. The mean has drifted up by about one second.",title:"Same data, two charts",figure:{kind:"control",title:"Call Set-up Time: I Chart vs Upper CuSum",xLabel:"Sample",panels:[{label:"Individual Value (s)",points:[10.2,9.6,10.4,9.9,10.1,9.7,10.9,11.1,10.8,11.3,11,11.2,11.4,11.1],cl:10,ucl:13,lcl:7,clLabel:"Target=10"},{label:"Upper CuSum",points:[0,0,0,0,0,0,.4,1,1.3,2.1,2.6,3.3,4.2,4.8],cl:0,ucl:4,flags:[{i:12,test:"1"},{i:13,test:"1"}],clLabel:"0"}]},callouts:["I chart: all inside 7–13 s, no signal","CuSum climbs from point 7","Crosses the limit (4) at point 13"]},{kind:"compare",say:"Cu Sum and E W M A both catch small shifts. The difference is memory. Cu Sum gives all past data equal weight. E W M A gives recent data more weight.",title:"CuSum vs EWMA",left:{head:"CuSum",points:["Small sustained shifts","All past data equal weight","Past as important as present"]},right:{head:"EWMA",points:["Small shifts, drift","Recent data weigh more","Good for autocorrelated data"]}},{kind:"callout",say:"Remember. Small shift, and past data as important as present data. That is Cu Sum.",big:"Small shift + history counts equally → CuSum",small:"Big, sudden shifts? A Shewhart chart is better."}]},{topic:"5.2.9",title:"EWMA Chart",oneLine:"An EWMA chart plots a smoothed average that gives recent points the most weight, so it catches small shifts and slow drift.",explain:["**EWMA** means **Exponentially Weighted Moving Average**. Instead of plotting each raw value, it plots a **weighted average** that mixes the newest value with all the older ones. Older data count **less and less**.","Use EWMA when you must detect a **small shift** or **slow drift** in the mean, especially when the data are **autocorrelated** — each value depends on the one before, like network load or room temperature. It is mostly used for **individual values**, sometimes for subgroup averages. The book says it is **infrequently used** because of the calculation, and is done with software.","How it works: each new plotted value = a small share (λ, lambda) of the new reading + the rest from the previous EWMA value. The book suggests **λ = 0.2**. A small λ means a long memory and more smoothing. λ = 1 gives an ordinary individuals chart.","Because the noise is smoothed out, the limits are **much tighter** than an I chart's. They start **narrow** and widen to a steady value. A small real shift shows up as the line **drifting steadily** toward a limit, then crossing it.","Remember: the points are **not the raw data**. Do not use the zone tests (9 in a row, etc.) on EWMA points."],example:`**Network latency.** Target = 50 ms, sigma = 2 ms, λ = 0.2.

- I chart limits would be 44 to 56 ms. No raw value goes beyond them.
- The EWMA limits settle at **48 to 52 ms** — much tighter.
- From point 9 the latency rises by about 1 sigma. The EWMA line drifts up: 50.4, 50.8, 51.0, 51.4, 51.5, 51.8, 51.9 … and crosses the UCL at **point 16 (52.17)**.
- Signal → investigate (for example a routing change). Small shifts are found, but not instantly — that is the price of smoothing.`,readIt:["The plotted line is a smoothed average, not the raw measurements.","A steady drift toward one limit = the mean is moving.","A point beyond the EWMA limits = signal → follow the OCAP.","Limits are narrow at the start and then become constant."],remember:["EWMA = Exponentially Weighted Moving Average; plots weighted values, not raw data.","Use for small shifts and drift, especially with autocorrelated data.","Recent data weigh most; older data less and less.","Book suggests λ = 0.2; smaller λ = more smoothing (longer memory).","Mostly for individuals; infrequently used; needs software."],traps:["Thinking EWMA plots the raw data — it plots weighted averages.","CuSum vs EWMA: EWMA weights recent data more; CuSum weights all history equally.","Choosing EWMA for big, sudden shifts — Shewhart charts react faster.",'Keyword match: "small shift" + "autocorrelation" → EWMA.'],video:[{kind:"title",say:"The E W M A chart. A smoothed line that catches small drifts.",title:"EWMA Chart",sub:"Exponentially weighted moving average"},{kind:"bullets",say:"E W M A stands for exponentially weighted moving average. Each plotted point mixes the newest value with the older ones. The newest value counts most, and older values count less and less. The book suggests a weight, lambda, of zero point two.",title:"The idea",bullets:["Plots a weighted average, not raw data","Recent data weigh most","Book suggests λ = 0.2","Good for autocorrelated data"]},{kind:"figure",say:"Here is network latency with a target of fifty milliseconds. The limits start narrow and settle at forty eight to fifty two. From point nine, latency rises a little. The smoothed line drifts steadily upward, and crosses the upper limit at point sixteen. An ordinary I chart, with limits of forty four to fifty six, shows no point beyond its limits.",title:"Latency drifting up",figure:{kind:"control",title:"EWMA Chart of Latency (λ = 0.2)",xLabel:"Sample",panels:[{label:"EWMA (ms)",points:[49.92,50.1,49.92,50.01,50.21,50.07,50.11,50.05,50.36,50.77,50.98,51.38,51.54,51.8,51.92,52.17],cl:50,ucl:[51.2,51.54,51.72,51.82,51.89,51.93,51.96,51.97,51.98,51.99,51.99,52,52,52,52,52],lcl:[48.8,48.46,48.28,48.18,48.11,48.07,48.04,48.03,48.02,48.01,48.01,48,48,48,48,48],flags:[{i:15,test:"1"}],clLabel:"Target=50"}]},callouts:["Limits start narrow, settle at 48–52","Steady drift up from point 9","Point 16 above UCL → signal"]},{kind:"decision",say:"When should you choose it? If you need to catch a small shift, and recent data matter more than old data, or the data are autocorrelated, choose E W M A. If all past data matter equally, choose Cu Sum.",title:"EWMA or CuSum?",question:"Small shift — should recent data weigh more?",yes:"EWMA (recent data weigh more)",no:"CuSum (all history equal)"},{kind:"callout",say:"Remember. Small shift, plus autocorrelated data, points to E W M A. It plots smoothed values, not raw data.",big:"Small shift + autocorrelation → EWMA",small:"Plots weighted averages. Book: lambda = 0.2."}]},{topic:"5.2.10",title:"Control Methods",oneLine:"Read a control chart by its centre line, limits and zones, use the special-cause tests to spot signals, and react with the OCAP — never adjust when there is no signal.",explain:["**Chart anatomy.** A control chart has a **centre line** (the average), an **upper control limit (UCL)** and a **lower control limit (LCL)** about **3 sigma** from the centre. For normal data they hold **99.73%** of natural variation. The limits come from the process data — they are the **voice of the process**. Specification limits are the **voice of the customer** and the book says **never** put them on a control chart.","**Two kinds of variation.** **Common cause** = the normal, random noise in every process — do **not** adjust for it. **Special cause** = something unusual with an assignable reason, shown by a point beyond a limit or a **pattern**. A process can be **in control but not capable** (stable, but still outside the specs).","**Zones.** Each half of the chart is split into three zones: **C** (within 1 sigma), **B** (1–2 sigma) and **A** (2–3 sigma). The tests use these zones.","**The tests.** Test 1: one point beyond 3 sigma. Test 2: **9 in a row** on one side of the centre line. Test 3: **6 in a row** steadily increasing or decreasing. Test 4: **14 in a row** alternating up and down. Tests 5–8 use the zones (2 of 3 in zone A, 4 of 5 in zone B or beyond, 15 in a row in zone C, 8 in a row outside zone C). **Only tests 1–4** apply to range, moving-range, S and attribute charts.","**Reacting.** Use the **Out-of-Control Action Plan (OCAP)** for every real signal. If there is **no signal, make no adjustment** — adjusting on every point (tampering) **increases** variation. Recalculate limits only after a **verified** process change or at a planned review. Note: **Pre-Control** is the only chart that uses spec limits."],example:`**Average handling time chart (I chart).** Centre line 50, sigma 2, limits 44 and 56.

- Points 7 to 15 are **all above 50** (51.0, 50.6, 51.8, 50.9, 52.3, 51.2, 50.4, 51.6, 51.1). None is near a limit, but it is **9 in a row** on one side → **Test 2**: the mean has shifted.
- Point 18 = **57** → beyond the UCL → **Test 1**. One point is enough; act at once.
- Points like 53 or 55 alone are inside the limits — **not** a signal by themselves.`,readIt:["Read the range / moving-range chart first when there is one; then the main chart.","Look for points beyond the limits (Test 1), then patterns: 9 on one side, 6 trending, 14 alternating.","Minitab marks a failing point in red with the test number.","Signal → follow the OCAP immediately. No signal → no adjustment.","After a fix, wait for the next sample; if it is back in control, change nothing more."],remember:["Control limits ≈ ±3σ = voice of the process; spec limits = voice of the customer; keep specs off control charts.","Test 1: 1 point beyond 3σ; Test 2: 9 in a row one side; Test 3: 6 trending; Test 4: 14 alternating.","Only tests 1–4 on R, MR, S and attribute charts.","Test 7 (15 in a row in zone C) = much less variation — still a special cause to investigate.","React with the OCAP; adjusting without a signal (tampering) increases variation.","Recalculate limits only after a verified change or a planned review."],traps:["Control limits are not spec limits — the chart shows stability, not whether the customer is happy.","Using 8 in a row for Test 2 — the exam and Minitab use 9.","A point near the limit but inside it is not a signal by itself.",'A pattern inside the limits (e.g. 9 in a row) IS a signal — "all points inside" does not mean "in control".'],video:[{kind:"title",say:"Control methods. How to read a control chart and how to react.",title:"Control Methods",sub:"Anatomy, tests and the OCAP"},{kind:"compare",say:"Every process has common cause variation. That is normal noise, so leave it alone. A special cause is something unusual, with a reason you can find. It shows up as a point beyond a limit, or a pattern.",title:"Two kinds of variation",left:{head:"Common cause",points:["Normal random noise","Inside limits, no pattern","Do not adjust"]},right:{head:"Special cause",points:["Unusual, assignable reason","Beyond a limit or a pattern","Investigate with the OCAP"]}},{kind:"figure",say:"Here is an I chart of handling time. The centre line is fifty, and the limits are forty four and fifty six. Points seven to fifteen are all above the centre line. Nine in a row on one side is test two. The mean has shifted. Point eighteen is beyond the upper limit. That is test one.",title:"Spot the signals",figure:{kind:"control",title:"I Chart of Handling Time",xLabel:"Observation",panels:[{label:"Individual Value",points:[49.2,51.1,48.4,50.3,47.9,49.6,51,50.6,51.8,50.9,52.3,51.2,50.4,51.6,51.1,48.7,50.2,57,49.5,50.8],cl:50,ucl:56,lcl:44,flags:[{i:14,test:"2"},{i:17,test:"1"}],clLabel:"X̄=50"}]},callouts:["UCL/LCL = centre ± 3σ (voice of the process)","Test 2: 9 in a row above the centre line","Test 1: point 18 beyond the UCL"]},{kind:"steps",say:"Learn the first four tests. They apply to every chart. Test one, one point beyond three sigma. Test two, nine in a row on one side. Test three, six in a row going up or down. Test four, fourteen in a row alternating up and down.",title:"Tests 1 to 4",steps:["1 point beyond 3σ","9 in a row on one side","6 in a row all up or all down","14 in a row alternating up and down"]},{kind:"decision",say:"Then react. Is there a signal? If yes, follow the out of control action plan straight away. If no, do nothing. Adjusting without a signal is tampering, and it makes variation worse.",title:"How to react",question:"Does any test show a signal?",yes:"Follow the OCAP now",no:"No adjustment (tampering adds variation)"},{kind:"callout",say:"Remember. Control limits are the voice of the process, not the customer. React to real signals, and only to real signals.",big:"React to signals with the OCAP — never tamper",small:"Control limits ≠ spec limits. Patterns inside limits are signals too."}]},{topic:"5.3.1",title:"Cost Benefit Analysis",oneLine:"Before a solution goes into the control plan, check that its impact is worth its cost and time — the book uses impact, cost and time ratings in an Improvement Selection Matrix.",explain:["Choosing which improvement to keep is a **business decision**. The book says a **cost benefit analysis is always a good tool** to set priorities. It balances different wishes (engineering, sales, operations) with numbers instead of opinions.","There are **three criteria**. **Impact**: how well does it fix the problem, long term? Best to worst: remove the root cause > monitor/flag the condition > inspect for defects > train people. **Cost**: **initial** (one-time: training current staff, new materials, building the fix, capital) and **on-going** (recurring: future training, inspection, monitoring, materials). **Time**: technical (minimum build time), political (competing priorities), cultural (time to win stakeholder support).","The **Improvement Selection Matrix** looks like the X-Y Matrix. The outputs (Y's) go across the top with significance ratings 1–10. Each improvement is rated for **impact on each output (0–7)**. Overall impact = the sum of impact × significance.","Then rate **cost (0–7, 7 = minimal cost)** and **time (0–7, 7 = under a week)**. **Overall rating = overall impact × cost × time.** The highest score wins. A **0 on cost or time** makes the score 0 — the option drops out, however big its impact.","The Control roadmap ends with **Verify Financial Impact**: the Champion, the Belt and Finance agree the benefits are real and the project is complete."],example:`**Cutting repeat calls in a contact centre.** Outputs: repeat calls (significance 10) and handling time (significance 7).

| Option | Impact | Overall impact | Cost | Time | Overall rating |
|---|---|---|---|---|---|
| A. Mandatory fields in the CRM | 6, 3 | 60 + 21 = 81 | 6 | 6 | **2,916** |
| B. Refresher training | 1, 1 | 10 + 7 = 17 | 7 | 7 | 833 |
| C. New CRM platform | 7, 5 | 70 + 35 = 105 | 1 | 0 | **0** |

Option A wins. Option C has the biggest impact, but it would take **over a year** (time = 0), so it drops out.`,readIt:["Multiply each impact rating by the output's significance and add → overall impact.","Overall rating = overall impact × cost rating × time rating; the highest is the best choice.","Any 0 for cost or time → overall rating 0 → removed.","Ratings are made by the whole team."],remember:["Three criteria: impact, cost, time.","Initial costs: training current staff, materials, build resources, capital. On-going: future training, inspection, monitoring, materials.","Time constraints: technical, political (competing priorities), cultural (stakeholder support).","Overall impact = Σ(impact × significance); overall rating = impact × cost × time.","Ratings 0–7; a 0 for cost or time removes the option.","Roadmap ends with Verify Financial Impact (Champion, Belt, Finance agree)."],traps:["A high impact cannot rescue an option rated 0 on cost or time.","Classifying monitoring or future training as initial costs — they are on-going.","Political vs cultural: political = competing priorities; cultural = winning stakeholder support.","Training is the weakest impact; removing the root cause is the strongest."],video:[{kind:"title",say:"Cost benefit analysis. Is the fix worth it?",title:"Cost Benefit Analysis",sub:"Impact, cost and time"},{kind:"bullets",say:"Choosing a solution is a business decision. The book rates every option on three things. Impact, which is how well it fixes the problem. Cost, both one time and ongoing. And time, which can be technical, political or cultural.",title:"Three criteria",bullets:["Impact: how well it fixes the problem","Cost: initial + on-going","Time: technical, political, cultural"]},{kind:"compare",say:"Know your costs. Initial costs are paid once, like training today’s staff, new materials or capital. On going costs repeat, like future training, inspection and monitoring.",title:"Two kinds of cost",left:{head:"Initial (one-time)",points:["Train current staff","New materials","Build resources, capital"]},right:{head:"On-going (recurring)",points:["Future training","Inspection","Monitoring, materials"]}},{kind:"steps",say:"The improvement selection matrix works like this. Rate each option’s impact on each output. Multiply by the output’s importance and add. Then multiply by the cost rating and the time rating. The highest score wins.",title:"Selection matrix",steps:["Rate impact on each output (0–7)","Impact × significance, then add","Rate cost and time (0–7)","Overall = impact × cost × time"]},{kind:"figure",say:"Here are three ways to cut repeat calls. Mandatory fields in the C R M score highest. A new C R M platform has the biggest impact, but it takes more than a year. Its time rating is zero, so its overall score is zero.",title:"Which option wins?",figure:{kind:"bars",title:"Overall Rating by Option",categories:["A. Mandatory CRM fields","B. Refresher training","C. New CRM platform"],series:[{name:"Overall rating",values:[2916,833,0]}],yLabel:"Impact × cost × time"},callouts:["A: 81 × 6 × 6 = 2,916 → best","B: training has low impact","C: time rating 0 → score 0, dropped"]},{kind:"callout",say:"Remember. Overall rating equals impact times cost times time. A zero on cost or time knocks the option out.",big:"Overall = impact × cost × time",small:"A 0 on cost or time removes the option."}]},{topic:"5.3.2",title:"Elements of the Control Plan",oneLine:"The control plan is the written summary of how the improved process will be kept in control after the team leaves, built from five elements: training, documentation, monitoring, response, and aligning systems and structures.",explain:["A **control plan** is a **written summary** of the methods used to monitor and control the process after the project. It records **all** the control methods, and it is a **living document** — updated when new measures or controls are added. It is the last physical result of the Control phase.","It does **not** replace detailed SOPs or work instructions. It **is** part of the final project report, kept to **track benefits** and as a reference if results are not sustained.","The book names **five elements** (memory aid T-D-M-R-A): **Training plan** — who needs training, who trains, and when (new hires, refreshers, and when the response plan shows performance getting worse). **Documentation plan** — process maps, SOPs, FMEA, manuals, kept current. **Monitoring plan** — what, when and how to measure (for example control charts, checklists, visual management). **Response plan** — what to do when monitoring shows a problem. **Aligning systems and structures** — goals, job descriptions and incentives that support the new way of working.","**Who?** The project team builds it with everyone who runs or changes the process. The Belt develops the monitoring plan, but the **process owner** is accountable after handover. The best way to win acceptance is **sign-off** by the area's supervisors and management.",'**Why?** To **sustain** the gains, so the Belt can move on, and so nobody needs to be a "constant hero" fixing the same problem again. Customers increasingly require control plans too.'],example:`**Control-plan row for P2 incident restore time (service desk).**

| Column | Entry |
|---|---|
| Characteristic | Mean restore time per day |
| Spec / target | ≤ 4 hours (SLA) |
| Measurement | ITSM ticket timestamps |
| Sample & frequency | Every P2 incident, daily mean |
| Control method | I-MR chart, tests 1–4 |
| Owner | Incident manager (process owner) |
| Reaction | Response plan RP-01 (OCAP) |

The 4-hour SLA is a **spec**: it goes in the specification column, **not** on the control chart.`,readIt:["Check that all five elements are present: training, documentation, monitoring, response, aligning systems.","Each controlled characteristic should have: what is measured, how and how often, the control method, an owner and the reaction.","Confirm it has been handed to the process owner and signed off by area management.","Keep it current: update it (and the FMEA) when the process or the controls change."],remember:["Control plan = written summary of the methods that monitor and control the process; a living document.","Five elements: training, documentation, monitoring, response, aligning systems and structures (T-D-M-R-A).","It does not replace SOPs or detailed instructions.","Process owner is accountable after handover; sign-off by area management.","Belt develops the monitoring plan; functional managers own adherence."],traps:['"Which is NOT an element?" — distractors like "project charter" or "hypothesis test plan".',"The Belt does not own the process after handover — the process owner does.","The control plan does not replace SOPs or work instructions.","Monitoring plan detects; response plan says what to do — do not mix them up."],video:[{kind:"title",say:"The control plan. How the gains are kept after the project team leaves.",title:"Elements of the Control Plan",sub:"Five elements — T D M R A"},{kind:"bullets",say:"A control plan is a written summary of how the process will be monitored and controlled. It is a living document. It does not replace the detailed work instructions. And after handover, the process owner is accountable for it.",title:"What it is",bullets:["Written summary of all control methods","Living document — keep it updated","Does not replace SOPs","Process owner accountable after handover"]},{kind:"steps",say:"It has five elements. Training, so people know the new way. Documentation, so the maps, procedures and F M E A are current. Monitoring, so we measure the right things. Response, so we know what to do when something goes wrong. And aligning systems and structures, like goals and incentives.",title:"The five elements",steps:["Training plan","Documentation plan","Monitoring plan","Response plan","Align systems & structures"]},{kind:"compare",say:"Two of these are easy to mix up. The monitoring plan detects problems. It says what to measure, when and how. The response plan acts on them. It says what to do, and who does it, when a problem appears.",title:"Monitoring vs response",left:{head:"Monitoring plan",points:["What, when, how to measure","Control charts, checklists","Detects the problem"]},right:{head:"Response plan",points:["What to do on a signal","Who acts, who is told","Fixes and records it"]}},{kind:"callout",say:"Remember the five elements. Training, documentation, monitoring, response, and aligning systems and structures.",big:"T-D-M-R-A: Training, Documentation, Monitoring, Response, Align",small:"Owned by the process owner after handover."}]},{topic:"5.3.3",title:"Elements of the Response Plan",oneLine:"The response plan says exactly what to do, and who does it, when monitoring shows a defect or an out-of-control signal.",explain:["A **response plan** is the process to follow when monitoring shows a **defect** or an **out-of-control condition**. It turns a chart signal into a fast, agreed action instead of panic or guesswork. It is one of the five elements of the control plan.","**Five triggers** start a response: (1) an **out-of-control point** on a chart; (2) **non-random behaviour within** the limits (a run, trend or pattern); (3) a condition **proven to produce defects** is present; (4) a **check-sheet failure**; (5) an **automation failure**. Note trigger 2: you respond even when every point is inside the limits.","**Five components** of each plan: **triggers** (usually the highest-risk X's from the FMEA), the **recommended response**, **responsibilities** (who acts, who is told or escalated to), **documentation that the plan was followed**, and **detailed information on the conditions** when the failure happened.","For control charts the response is written as an **OCAP** (Out-of-Control Action Plan) — a flowchart of checks and actions in order. Respond **immediately** to real signals, and **only** to real signals. After a fix, wait for the next sample; if it is back in control, change nothing more.","Each failure is recorded in an **abnormality report** (like an ISO 9000 Corrective Action Request). Counting these reports shows which failures keep coming back. Response plans are living documents, and responding to poor results must be part of **training**."],example:`**Disputed invoices (billing).** A P chart tracks the daily proportion of disputed invoices: $\\bar{p} = 0.04$, $n = 200$ per day, UCL = 0.0816 (about **17 or more** disputes in a day).

**Response plan row:**
- *Trigger:* 17+ disputes in a day, **or** 9 days in a row above 4%.
- *Recommended response:* check the tariff-table load log first; if it changed, roll back and hold the bill run.
- *Responsibility:* billing shift lead; escalate to the billing manager within 1 hour.
- *Documentation:* abnormality report in the ticket tool.
- *Conditions:* record bill cycle, tariff version and product mix.

Day 12 had 18 disputes (0.09 > 0.0816) → the plan is triggered.`,readIt:["Check the trigger list: points beyond limits AND patterns inside the limits both count.","For each trigger, the plan must say what to do, who does it, how it is recorded, and what conditions to note.","No signal → no action (the OCAP is not used).","After a correction, wait for the next sample before doing anything more."],remember:["Response plan = what to do when monitoring shows a defect or an out-of-control condition.","Five triggers: OOC point, pattern within limits, defect-causing condition, check-sheet failure, automation failure.","Five components: triggers, recommended response, responsibilities, proof it was followed, conditions.","On charts the response is the OCAP; act only on real signals.","Abnormality report = detailed record of each failure (like an ISO 9000 CAR)."],traps:['"All points are inside the limits, so no action" — wrong if a pattern breaks the rules (e.g. 9 in a row).',"Adjusting whenever a point is above the centre line is tampering, not a response plan.",'Distractors like "capital budget" or "project charter" are not components of a response plan.',"Monitoring plan detects; response plan says what to do after detection."],video:[{kind:"title",say:"The response plan. What to do when the chart says something is wrong.",title:"Elements of the Response Plan",sub:"Triggers, actions, owners, records"},{kind:"figure",say:"Here is a P chart of disputed invoices. Two hundred invoices are checked each day. The upper limit is about eight percent. On day twelve, nine percent of invoices were disputed. That point is beyond the limit, so the response plan is triggered.",title:"A trigger on the chart",figure:{kind:"control",title:"P Chart of Disputed Invoices (n = 200)",xLabel:"Day",panels:[{label:"Proportion",points:[.035,.045,.04,.03,.05,.04,.035,.045,.055,.04,.035,.09,.04],cl:.04,ucl:.0816,lcl:0,flags:[{i:11,test:"1"}],clLabel:"P̄=0.04"}]},callouts:["UCL = 0.0816 (≈ 17+ disputes a day)","Day 12: 18 disputes = 0.09","Beyond UCL → response plan starts"]},{kind:"bullets",say:"A response is also triggered by a pattern inside the limits, by a condition known to cause defects, by a failed check sheet, or by an automation failure. Not only by a point outside the limits.",title:"Five triggers",bullets:["Point beyond a control limit","Pattern inside the limits","Defect-causing condition present","Check-sheet or automation failure"]},{kind:"steps",say:"Every response plan has five parts. The trigger. The recommended response. Who is responsible. Proof that the plan was followed. And details of the conditions when it happened.",title:"Five components",steps:["Trigger (highest-risk X’s)","Recommended response","Responsibilities & escalation","Proof the plan was followed","Conditions at the time"]},{kind:"decision",say:"And the golden rule. Is there a real signal? If yes, follow the plan now, and record it in an abnormality report. If no, do nothing. Adjusting without a signal makes things worse.",title:"Act or wait?",question:"Is there a real signal (a trigger)?",yes:"Follow the OCAP and record it",no:"No action — do not tamper"},{kind:"callout",say:"Remember. The monitoring plan detects. The response plan says what to do, and who does it.",big:"Response plan = what to do when out of control",small:"Patterns inside the limits are triggers too."}]},{topic:"chart-map",title:"Which control chart do I use?",oneLine:"Pick the chart by asking: what type of data, what subgroup size, defects or defectives, is the sample size constant, and do I need to catch small shifts?",explain:["**Question 1 — what type of data?** **Continuous** (variables) data are measured on a scale: handling time, latency, temperature. **Attribute** data are counted: number of failed activations, errors per form. Prefer continuous data when you can — it carries more information.","**Continuous data → look at the subgroup size.** Subgroup of **1** → **I-MR** (individuals and moving range). Subgroup **2–5** → **Xbar-R** (mean and range). Subgroup **10 or more** → **Xbar-S** (mean and standard deviation).","**Attribute data → defectives or defects?** A **defective** is a whole unit that is good or bad (a failed activation). A **defect** is one flaw, and a unit can have many (three errors on one form). Defectives → **NP or P**. Defects → **C or U**.","**Then: is the sample size constant?** Constant → the **count** charts: **NP** (defectives) or **C** (defects). Varying → the **rate** charts: **P** (proportion defective) or **U** (defects per unit). P and U limits step up and down with n.",'**Special cases — small shifts.** If you must catch a **small shift** in the mean, use **CuSum** (all past data count equally — "past as important as present") or **EWMA** (recent data weigh more; good for autocorrelated data). For large, sudden shifts, the ordinary (Shewhart) charts are best.'],example:`**Quick practice (telecom).**

| Situation | Chart |
|---|---|
| One latency reading every hour | **I-MR** |
| 4 test calls timed every hour | **Xbar-R** |
| 12 test calls timed every hour | **Xbar-S** |
| Exactly 200 handsets tested daily, count failures | **NP** |
| Activations vary daily, % failed | **P** |
| Same 50 forms checked daily, count errors | **C** |
| Forms checked vary daily, errors per form | **U** |
| Catch a small drift in autocorrelated network load | **EWMA** |
| Catch a small shift; all history equally important | **CuSum** |`,readIt:["Measured on a scale → continuous → choose by subgroup size (1 / 2–5 / 10+).","Counted → attribute → defectives (good/bad unit) or defects (flaws)?","Constant sample size → NP or C. Varying → P or U.","Small shift needed → CuSum (equal weight) or EWMA (recent weight, autocorrelation)."],remember:["I-MR = subgroup 1; Xbar-R = 2–5; Xbar-S = 10 or more.","Defectives: NP (constant n), P (varying n).","Defects: C (constant n), U (varying n).","P and U limits vary with sample size; NP and C limits are flat.","Small shifts: CuSum (all history equal) or EWMA (recent data weigh more)."],traps:["Choosing P or U just because n varies — first decide defectives (P) or defects (U).","Choosing C or NP when the sample size varies — they need constant n.","Using Xbar-R for subgroups of 10 or more — use Xbar-S.","Choosing CuSum or EWMA for large sudden shifts — Shewhart charts are better there."],video:[{kind:"title",say:"Which control chart do I use? Four quick questions take you to the right chart.",title:"Which control chart do I use?",sub:"The chart selection map"},{kind:"decision",say:"Question one. Is the data measured on a scale, like handling time or latency? Then it is continuous data. If it is counted, like failed activations or errors on a form, it is attribute data.",title:"Type of data",question:"Is the data measured on a scale?",yes:"Continuous → I-MR, Xbar-R, Xbar-S",no:"Attribute (counts) → NP, P, C, U"},{kind:"steps",say:"For continuous data, look at the subgroup size. One reading at a time, use I M R. Two to five readings, use X bar R. Ten or more readings, use X bar S.",title:"Continuous: subgroup size",steps:["Subgroup 1 → I-MR","Subgroup 2 to 5 → Xbar-R","Subgroup 10 or more → Xbar-S"]},{kind:"decision",say:"For attribute data, ask question two. Is each unit simply good or bad? That is a defective, so use N P or P. If you count flaws, and one unit can have many, those are defects. Use C or U.",title:"Defectives or defects?",question:"Is each unit simply good or bad?",yes:"Defectives → NP or P",no:"Defects (many per unit) → C or U"},{kind:"decision",say:"Question three. Is the sample size the same every time? If yes, use a count chart. N P for defectives, C for defects. If the sample size changes, use a rate chart. P for defectives, U for defects. Their limits step up and down with the sample size.",title:"Constant sample size?",question:"Is the sample size the same every time?",yes:"NP (defectives) or C (defects)",no:"P (defectives) or U (defects)"},{kind:"decision",say:"Question four, the special case. Do you need to catch a small shift? Then use Cu Sum or E W M A. Cu Sum gives all past data equal weight. E W M A gives recent data more weight, and suits autocorrelated data. For big, sudden shifts, stay with the normal charts.",title:"Small shifts?",question:"Must you catch a small shift in the mean?",yes:"CuSum (all history) or EWMA (recent, autocorrelated)",no:"Standard Shewhart chart"},{kind:"callout",say:"Remember the map. Data type, then subgroup size, or defectives versus defects, then constant or varying sample size. And for small shifts, Cu Sum or E W M A.",big:"Data type → subgroup size or defect type → constant n? → small shift?",small:"NP/C = constant n · P/U = varying n · CuSum/EWMA = small shifts"}]}],t=["5.1.1","5.1.2","5.1.3","5.2.1","5.2.2","5.2.3","5.2.4","5.2.5","5.2.6","5.2.7","5.2.8","5.2.9","5.2.10","5.3.1","5.3.2","5.3.3","chart-map"],a=[...m,...p].sort((e,s)=>t.indexOf(e.topic)-t.indexOf(s.topic));Object.fromEntries(a.map(e=>[e.topic,e]));const g={phase:"Control",lessons:a,base:"/control-coach",videoDir:"videos/control",storeKey:"sv-coach-control",mapTopic:"chart-map",mapSection:"5.2",mapPool:e=>e.phase===5&&e.topic.startsWith("5.2")&&(e.qtype==="best-action"||e.qtype==="scenario"),theme:{text:"text-coral",bg:"bg-coral",soft:"bg-coral/10",softer:"bg-coral/5"}};function A(){return o.jsx(i,{cfg:g})}export{A as default};
